export const TIME_SIGNATURES = [
  '2/4',
  '3/4',
  '4/4',
  '5/4',
  '3/8',
  '6/8',
  '7/8',
  '9/8',
  '12/8',
] as const;
export type TimeSignature = typeof TIME_SIGNATURES[number];
export const DEFAULT_TIME_SIGNATURE: TimeSignature = '4/4';

export const getTimeSignature = (value: unknown): TimeSignature =>
  TIME_SIGNATURES.includes(value as TimeSignature)
    ? (value as TimeSignature)
    : DEFAULT_TIME_SIGNATURE;

// BPM and the editor grid count quarters, including in eighth-note meters.
export const getBeatsPerMeasure = (value?: TimeSignature) => {
  const [beats, unit] = getTimeSignature(value).split('/').map(Number);
  return (beats * 4) / unit;
};
