import {
  TIME_SIGNATURES,
  TimeSignature,
} from 'app/services/MelodiesService/meter';
import { optimizeMelodyScale } from 'app/services/MelodiesService/scaleOptimization';
import type { Melody } from 'app/services/MelodiesService/types';
import { chromaticNotes } from 'app/services/NotesService/chromaticNotes';
import type { Note, Octave } from 'app/services/NotesService/types';
import { timbresLinks } from 'app/services/SynthesizerService/timbres';
import type { Timbre } from 'app/services/SynthesizerService/types';

import { ImportedTrack, RawImportNote } from './types';

export const timbreForProgram = (
  program: number,
  percussion: boolean,
): Timbre => {
  let preferred: string;
  if (percussion) preferred = 'drums';
  else if (program === 21 || program === 22) preferred = 'Accordion';
  else if (program === 4 || program === 5) preferred = 'electricPiano';
  else if (program < 8) preferred = 'studioResonantPiano';
  else if (program === 11) preferred = 'vibraphone';
  else if (program === 12) preferred = 'marimba';
  else if (program < 16) preferred = 'glockenspiel';
  else if (program < 24) preferred = 'organ';
  else if (program < 32)
    preferred = program >= 29 ? 'distortedGuitar' : 'guitar';
  else if (program < 40) preferred = 'EBM Bass';
  else if (program === 42) preferred = 'cello';
  else if (program === 45) preferred = 'pizzicato';
  else if (program === 46) preferred = 'harp';
  else if (program >= 52 && program <= 54) preferred = 'choirPad';
  else if (program < 56) preferred = 'strings';
  else if (program < 64) preferred = 'trumpet';
  else if (program < 68) preferred = 'tenorSax';
  else if (program === 71) preferred = 'flute';
  else if (program < 80) preferred = 'flute';
  else if (program < 88) preferred = 'synthLead';
  else if (program < 104) preferred = 'warmPad';
  else if (program === 105) preferred = 'banjo';
  else preferred = 'guitar';
  return (
    timbresLinks.find(({ title }) => title === preferred)?.title ??
    timbresLinks[0].title
  );
};

export const createImportedTrack = (options: {
  id: string;
  title: string;
  name: string;
  author?: string;
  bpm: number;
  meter: number[];
  program: number;
  percussion: boolean;
  notes: RawImportNote[];
  warnings?: string[];
}): ImportedTrack => {
  const warnings = [...(options.warnings ?? [])];
  const signature = options.meter.join('/');
  const timeSignature = TIME_SIGNATURES.includes(signature as TimeSignature)
    ? (signature as TimeSignature)
    : '4/4';
  if (timeSignature !== signature)
    warnings.push(
      `Размер ${signature} отображается как 4/4. Время нот сохранено.`,
    );
  const notes: Melody['notes'] = [];
  let skipped = 0;
  options.notes.forEach(note => {
    const pitch = note.midi + (options.percussion ? 12 : 0);
    if (
      !Number.isInteger(pitch) ||
      pitch < 12 ||
      pitch > 119 ||
      !Number.isFinite(note.start) ||
      note.start < 0 ||
      !Number.isFinite(note.duration) ||
      note.duration <= 0
    ) {
      skipped++;
      return;
    }
    notes.push({
      note: `${chromaticNotes[pitch % 12]}${
        Math.floor(pitch / 12) - 1
      }` as Note,
      start: note.start,
      duration: note.duration,
    });
  });
  notes.sort((a, b) => a.start - b.start || a.note.localeCompare(b.note));
  if (skipped)
    warnings.push(
      `Пропущено нот: ${skipped}. Поддерживается диапазон C0–B8 и положительные длительности.`,
    );
  if (options.bpm < 40 || options.bpm > 220)
    warnings.push(
      'BPM файла сохранён; метроном ограничен диапазоном 40–220 BPM.',
    );
  warnings.push(
    'Звук заменён доступным тембром Qwertophone. Громкость отдельных нот, изгибы высоты и исходные эффекты не переносятся.',
  );
  const firstPitch = notes[0]?.note ?? 'C3';
  const octave = Math.max(
    1,
    Math.min(4, Number(firstPitch.slice(-1))),
  ) as Octave;
  return {
    id: options.id,
    name: options.name,
    melody: optimizeMelodyScale({
      title:
        options.title === options.name
          ? options.title
          : `${options.title} · ${options.name}`,
      author: options.author,
      scale: 'chromatic',
      mode: 'chromatic',
      pitch: 0,
      octave,
      timbre: timbreForProgram(options.program, options.percussion),
      bpm: options.bpm,
      timeSignature,
      notes,
    }),
    warnings: Array.from(new Set(warnings)),
  };
};
