import { Midi } from '@tonejs/midi';
import type { Header } from '@tonejs/midi/dist/Header';
import type { Track } from '@tonejs/midi/dist/Track';

import { createImportedTrack } from './convert';
import {
  ImportedSong,
  MAX_IMPORT_NOTES,
  MelodyImportError,
  RawImportNote,
} from './types';

export const decodeMidiText = (text: string) => {
  if (Array.from(text).some(char => char.charCodeAt(0) > 255))
    return text.trim();
  try {
    return new TextDecoder('utf-8', { fatal: true })
      .decode(Uint8Array.from(text, char => char.charCodeAt(0)))
      .trim();
  } catch {
    return text.trim();
  }
};

export const normalizeHeader = (header: Header) => {
  if (!header.tempos.some(event => event.ticks === 0))
    header.tempos.unshift({ ticks: 0, bpm: 120 });
  if (
    header.tempos.some(event => !Number.isFinite(event.bpm) || event.bpm <= 0)
  ) {
    throw new MelodyImportError('В файле указан некорректный темп.');
  }
  header.update();
  return {
    bpm: header.tempos[0].bpm,
    meter: header.timeSignatures.find(event => event.ticks === 0)
      ?.timeSignature ?? [4, 4],
    warnings: [
      ...(new Set(header.tempos.map(event => event.bpm)).size > 1
        ? [
            'В файле меняется темп. Время нот сохранено; сетка и экспорт используют начальный BPM.',
          ]
        : []),
      ...(header.timeSignatures.some(event => event.ticks > 0)
        ? [
            'В файле меняется размер. Время нот сохранено; отображается начальный размер.',
          ]
        : []),
    ],
  };
};

export const getMidiTrackNotes = (
  track: Track,
  header: Header,
): RawImportNote[] => {
  const pedals = (track.controlChanges[64] ?? [])
    .slice()
    .sort((a, b) => a.ticks - b.ticks);
  const intervals: { start: number; end: number }[] = [];
  const trackEnd = Math.max(
    track.endOfTrackTicks ?? 0,
    ...track.notes.map(note => note.ticks + note.durationTicks),
    ...pedals.map(event => event.ticks),
  );
  let pressed: number | undefined;
  pedals.forEach(event => {
    if (event.value >= 0.5) pressed ??= event.ticks;
    else if (pressed !== undefined) {
      intervals.push({ start: pressed, end: event.ticks });
      pressed = undefined;
    }
  });
  if (pressed !== undefined) intervals.push({ start: pressed, end: trackEnd });
  const byPitch = new Map<number, number[]>();
  track.notes.forEach(note => {
    const starts = byPitch.get(note.midi) ?? [];
    starts.push(note.ticks);
    byPitch.set(note.midi, starts);
  });
  byPitch.forEach(starts => starts.sort((a, b) => a - b));
  return track.notes.map(note => {
    let end = note.ticks + note.durationTicks;
    const held = intervals.find(
      interval => interval.start <= end && end < interval.end,
    );
    if (held) {
      end = held.end;
      const attack = byPitch
        .get(note.midi)
        ?.find(
          tick => tick > note.ticks && tick >= note.ticks + note.durationTicks,
        );
      if (attack !== undefined) end = Math.min(end, attack);
    }
    const start = header.ticksToSeconds(note.ticks) * 1000;
    return {
      midi: note.midi,
      start,
      duration: header.ticksToSeconds(end) * 1000 - start,
    };
  });
};

export const parseMidiFile = (
  data: Uint8Array,
  filename: string,
): ImportedSong => {
  if (
    data.length < 14 ||
    String.fromCharCode(...Array.from(data.slice(0, 4))) !== 'MThd'
  ) {
    throw new MelodyImportError(
      'Это не MIDI-файл или его заголовок повреждён.',
    );
  }
  const format = data[8] * 256 + data[9];
  if (format > 1 || data[12] & 0x80)
    throw new MelodyImportError(
      'Поддерживаются MIDI форматов 0 и 1 с музыкальным временем PPQ. SMPTE и формат 2 не поддерживаются.',
    );
  let midi: Midi;
  try {
    midi = new Midi(data);
  } catch {
    throw new MelodyImportError(
      'Не удалось прочитать MIDI. Возможно, файл повреждён.',
    );
  }
  if (
    midi.tracks.reduce((sum, track) => sum + track.notes.length, 0) >
    MAX_IMPORT_NOTES
  )
    throw new MelodyImportError(
      'В файле больше 50000 нот. Выберите файл с меньшим количеством партий.',
    );
  const metadata = normalizeHeader(midi.header);
  const title = decodeMidiText(midi.name) || filename.replace(/\.[^.]+$/, '');
  const tracks = midi.tracks
    .filter(track => track.notes.length)
    .map((track, index) =>
      createImportedTrack({
        ...metadata,
        id: String(index),
        title,
        name: decodeMidiText(track.name) || `Дорожка ${index + 1}`,
        program: track.instrument.number,
        percussion: track.instrument.percussion,
        notes: getMidiTrackNotes(track, midi.header),
      }),
    );
  if (!tracks.some(track => track.melody.notes.length))
    throw new MelodyImportError('В файле нет доступных нот в диапазоне C0–B8.');
  return { title, format: 'MIDI', tracks };
};
